**What this code covers**

- Specialized Research MCP Server with advanced tools: - Multi-source search - Document summarization - Fact verification - Citation generation
- Deep search across multiple knowledge sources. sources: list of ['academic', 'news', 'technical', 'general']
- Summarize text in different styles. style: 'bullet', 'paragraph', 'executive'
- Verify a factual claim and return confidence score.

**Defines:** `deep_search()`, `summarize_text()`, `verify_fact()`, `generate_citation()`, `ai_papers()`

```python name=mcp_agents/servers/research_server.py
"""
Specialized Research MCP Server with advanced tools:
- Multi-source search
- Document summarization
- Fact verification
- Citation generation
"""
import json
from fastmcp import FastMCP

mcp = FastMCP(
    name        = "ResearchServer",
    description = "Advanced research tools for AI agents",
)

@mcp.tool()
def deep_search(query: str, sources: list[str] = None) -> str:
    """
    Deep search across multiple knowledge sources.
    sources: list of ['academic', 'news', 'technical', 'general']
    """
    if not sources:
        sources = ["general"]

    results = {}
    knowledge = {
        "academic": {
            "rag":        "Academic: RAG was introduced in 'Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks' (Lewis et al., 2020).",
            "agents":     "Academic: AI Agents formalized in 'ReAct: Synergizing Reasoning and Acting in Language Models' (Yao et al., 2022).",
            "mcp":        "Academic: MCP (Model Context Protocol) introduced by Anthropic in 2024 as open standard.",
        },
        "technical": {
            "fastmcp":    "Technical: FastMCP v2 supports tools, resources, prompts via decorators. Run with stdio or HTTP.",
            "langchain":  "Technical: LangChain LCEL uses pipe operator (|) for composing chains.",
            "langgraph":  "Technical: LangGraph StateGraph uses TypedDict for state management.",
        },
        "news": {
            "ai":         "News: AI agents market expected to reach $47B by 2030 (2024 report).",
            "mcp":        "News: MCP adopted by Claude, Cursor, Windsurf, and major AI frameworks in 2024.",
        },
        "general": {
            "mcp":        "General: MCP standardizes how LLMs connect to tools, like USB-C for AI.",
            "agents":     "General: AI agents can autonomously complete multi-step tasks using tools.",
            "rag":        "General: RAG improves LLM accuracy by retrieving relevant documents.",
        }
    }

    for source in sources:
        src_kb = knowledge.get(source, {})
        q_lower = query.lower()
        for key, val in src_kb.items():
            if any(w in q_lower for w in key.split()):
                results[source] = results.get(source, []) + [val]

    if not results:
        results = {"general": [f"Research results for: {query}"]}

    return json.dumps({"query": query, "sources": sources, "results": results})

@mcp.tool()
def summarize_text(text: str, max_words: int = 100,
                   style: str = "bullet") -> str:
    """
    Summarize text in different styles.
    style: 'bullet', 'paragraph', 'executive'
    """
    words  = text.split()
    length = len(words)
    if style == "bullet":
        lines  = text.split(".")[:3]
        summary = "\n".join([f"• {l.strip()}" for l in lines if l.strip()])
    elif style == "executive":
        summary = f"EXECUTIVE SUMMARY: {' '.join(words[:max_words//2])}..."
    else:
        summary = " ".join(words[:max_words]) + ("..." if length > max_words else "")

    return json.dumps({
        "original_words": length,
        "summary":        summary,
        "style":          style,
        "compressed_to":  f"{min(max_words, length)} words",
    })

@mcp.tool()
def verify_fact(claim: str) -> str:
    """
    Verify a factual claim and return confidence score.
    Returns: verified status, confidence, and explanation.
    """
    known_facts = {
        "openai founded 2015":  (True,  0.99, "OpenAI was founded December 2015."),
        "python created 1991":  (True,  0.99, "Python first released in 1991 by Guido van Rossum."),
        "mcp by anthropic":     (True,  0.95, "MCP was introduced by Anthropic in 2024."),
        "gpt4 by openai":       (True,  0.99, "GPT-4 was released by OpenAI in March 2023."),
        "langchain 2022":       (True,  0.95, "LangChain was launched in October 2022."),
    }

    claim_lower = claim.lower()
    for key, (verified, conf, explanation) in known_facts.items():
        if any(w in claim_lower for w in key.split() if len(w) > 3):
            return json.dumps({
                "claim":       claim,
                "verified":    verified,
                "confidence":  conf,
                "explanation": explanation,
            })

    return json.dumps({
        "claim":       claim,
        "verified":    None,
        "confidence":  0.5,
        "explanation": f"Cannot verify: '{claim}' — insufficient data.",
    })

@mcp.tool()
def generate_citation(source: str, style: str = "APA") -> str:
    """
    Generate a citation for a source in various styles.
    style: 'APA', 'MLA', 'Chicago'
    """
    citations = {
        "ReAct": {
            "APA":     "Yao, S. et al. (2022). ReAct: Synergizing Reasoning and Acting in Language Models. arXiv:2210.03629.",
            "MLA":     'Yao, Shunyu, et al. "ReAct: Synergizing Reasoning and Acting." arXiv (2022).',
            "Chicago": "Yao, Shunyu et al. 2022. 'ReAct: Synergizing Reasoning and Acting.' arXiv:2210.03629.",
        },
        "RAG": {
            "APA":     "Lewis, P. et al. (2020). Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks. NeurIPS.",
            "MLA":     'Lewis, Patrick, et al. "Retrieval-Augmented Generation." NeurIPS (2020).',
            "Chicago": "Lewis, Patrick et al. 2020. 'Retrieval-Augmented Generation.' NeurIPS.",
        },
    }

    for key, styles in citations.items():
        if key.lower() in source.lower():
            return json.dumps({
                "source":   source,
                "style":    style,
                "citation": styles.get(style, styles["APA"]),
            })

    return json.dumps({
        "source":   source,
        "style":    style,
        "citation": f"[{source}] (Retrieved {__import__('datetime').datetime.now().year})",
    })

@mcp.resource("knowledge://ai-papers")
def ai_papers() -> str:
    """List of key AI papers and their summaries."""
    return json.dumps([
        {"title": "Attention Is All You Need", "year": 2017,
         "summary": "Introduced the Transformer architecture."},
        {"title": "GPT-3", "year": 2020,
         "summary": "175B parameter language model with few-shot learning."},
        {"title": "ReAct", "year": 2022,
         "summary": "Combines reasoning and acting in language models."},
        {"title": "RAG", "year": 2020,
         "summary": "Retrieval-augmented generation for knowledge tasks."},
        {"title": "Tree of Thoughts", "year": 2023,
         "summary": "Deliberate problem solving with multiple reasoning paths."},
    ])

if __name__ == "__main__":
    mcp.run(transport="stdio")
```

**What this code covers**

- Code Execution MCP Server: - Execute Python code safely - Run tests - Format code - Analyze code complexity
- Execute Python code in a safe sandbox.
- Analyze Python code for complexity, issues, and metrics.
- Format Python code with proper indentation.
- Basic formatting — in production use black or autopep8

**Defines:** `execute_python()`, `analyze_code()`, `format_code()`, `generate_code()`, `Item`, `get_item()`, `create_item()`, `Entity`, `process()`, `TestMyFunction`

```python name=mcp_agents/servers/code_server.py
"""
Code Execution MCP Server:
- Execute Python code safely
- Run tests
- Format code
- Analyze code complexity
"""
import json
import math
import ast
import textwrap
from fastmcp import FastMCP

mcp = FastMCP(
    name        = "CodeServer",
    description = "Code execution and analysis tools",
)

@mcp.tool()
def execute_python(code: str, timeout: int = 10) -> str:
    """
    Execute Python code in a safe sandbox.
    Returns stdout, result, or error.
    """
    import io, contextlib

    # Safe builtins whitelist
    safe_globals = {
        "__builtins__": {
            "print": print, "len": len, "range": range,
            "str": str, "int": int, "float": float,
            "list": list, "dict": dict, "tuple": tuple,
            "set": set, "bool": bool, "type": type,
            "enumerate": enumerate, "zip": zip, "map": map,
            "filter": filter, "sorted": sorted, "sum": sum,
            "min": min, "max": max, "abs": abs, "round": round,
        },
        "math": math,
        "json": json,
    }

    stdout_capture = io.StringIO()
    result         = None
    error          = None

    try:
        with contextlib.redirect_stdout(stdout_capture):
            exec(code, safe_globals)
        stdout = stdout_capture.getvalue()
    except Exception as e:
        error  = str(e)
        stdout = stdout_capture.getvalue()

    return json.dumps({
        "code":   code[:200],
        "stdout": stdout,
        "error":  error,
        "status": "error" if error else "success",
    })

@mcp.tool()
def analyze_code(code: str) -> str:
    """
    Analyze Python code for complexity, issues, and metrics.
    Returns: lines, functions, classes, complexity estimate.
    """
    try:
        tree          = ast.parse(code)
        functions     = [n.name for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)]
        classes       = [n.name for n in ast.walk(tree) if isinstance(n, ast.ClassDef)]
        imports       = [ast.dump(n) for n in ast.walk(tree) if isinstance(n, (ast.Import, ast.ImportFrom))]
        lines         = len(code.split("\n"))
        complexity    = len(functions) * 2 + len(classes) * 3

        return json.dumps({
            "lines":       lines,
            "functions":   functions,
            "classes":     classes,
            "num_imports": len(imports),
            "complexity":  complexity,
            "grade":       "A" if complexity < 10 else "B" if complexity < 20 else "C",
        })
    except SyntaxError as e:
        return json.dumps({"error": f"Syntax error: {e}"})

@mcp.tool()
def format_code(code: str) -> str:
    """
    Format Python code with proper indentation.
    """
    try:
        # Basic formatting — in production use black or autopep8
        dedented = textwrap.dedent(code).strip()
        return json.dumps({"formatted": dedented, "status": "success"})
    except Exception as e:
        return json.dumps({"error": str(e)})

@mcp.tool()
def generate_code(task: str, language: str = "python") -> str:
    """
    Generate code template for common tasks.
    task: 'rest_api', 'data_class', 'async_function', 'unit_test'
    """
    templates = {
        "rest_api": '''
from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

class Item(BaseModel):
    name: str
    value: float

@app.get("/items/{item_id}")
async def get_item(item_id: int):
    return {"item_id": item_id}

@app.post("/items/")
async def create_item(item: Item):
    return item
''',
        "data_class": '''
from dataclasses import dataclass, field
from typing import Optional

@dataclass
class Entity:
    id: int
    name: str
    tags: list[str] = field(default_factory=list)
    metadata: Optional[dict] = None

    def to_dict(self) -> dict:
        return {"id": self.id, "name": self.name}
''',
        "async_function": '''
import asyncio
from typing import Any

async def process(data: Any, timeout: float = 30.0) -> dict:
    """Process data asynchronously with timeout."""
    try:
        async with asyncio.timeout(timeout):
            result = await asyncio.sleep(0)  # Replace with actual async work
            return {"status": "success", "data": data}
    except asyncio.TimeoutError:
        return {"status": "timeout", "data": None}
    except Exception as e:
        return {"status": "error", "error": str(e)}
''',
        "unit_test": '''
import pytest
from unittest.mock import Mock, patch

class TestMyFunction:
    def test_basic_case(self):
        result = my_function("input")
        assert result == "expected"

    def test_edge_case(self):
        with pytest.raises(ValueError):
            my_function(None)

    @patch("module.dependency")
    def test_with_mock(self, mock_dep):
        mock_dep.return_value = "mocked"
        result = my_function("input")
        assert mock_dep.called
''',
    }

    template = templates.get(task.lower(), f"# Code template for: {task}\n# TODO: implement")
    return json.dumps({
        "task":     task,
        "language": language,
        "code":     template.strip(),
    })

@mcp.resource("examples://python-patterns")
def python_patterns() -> str:
    return """
# Python Design Patterns

## Singleton
class Singleton:
    _instance = None
    def __new__(cls):
        if not cls._instance:
            cls._instance = super().__new__(cls)
        return cls._instance

## Observer
class EventEmitter:
    def __init__(self):
        self._listeners = {}
    def on(self, event, fn):
        self._listeners.setdefault(event, []).append(fn)
    def emit(self, event, *args):
        for fn in self._listeners.get(event, []):
            fn(*args)
"""

if __name__ == "__main__":
    mcp.run(transport="stdio")
```
